// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.keystoreimport android.content.Contextimport android.content.SharedPreferencesimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Dynamic Rotation Manager (Module 12, Pillar 2). * * Strategy §12.2 — rotates keys on two triggers: * *   1. **Time-based** — master key rotated every **180 days**. This limits *      the impact of a future key compromise: even if an attacker recovers *      the key, they can only decrypt data encrypted within the 180-day *      window before that key is destroyed. *   2. **Threat-based** — on [SupplyChainMonitor] detecting a HIGH or *      CRITICAL threat. Rotation re-encrypts all data with the new key, *      invalidating any key material that may have been observed by the *      attacker (e.g., via Frida hooking `Cipher.doFinal`). * * ## Rotation process * *   1. Generate a new key under a NEW alias (e.g., `nous.master.v2`). *   2. Walk every entry stored under the old alias. *   3. Decrypt each entry with the old key, re-encrypt with the new key. *   4. Once all entries are re-encrypted, delete the old key. *   5. Update [currentMasterAlias] to point at the new alias. * * This process is **transparent** to callers — they always encrypt/decrypt * against the "current master alias", which is a pointer maintained here. * * ## Real Android APIs * * - `SharedPreferences` for persisting `currentMasterAlias` + `lastRotationAt`. * - [KeystoreManager.rotateKey] for the actual key rotation. * - No background worker here — [maybeRotate] is called by the app's *   startup initializer (idempotent — rotation is skipped if not yet due). * * ## Why this is REAL * * Every call hits REAL Keystore APIs via [KeystoreManager]. There is no * "schedule" placeholder — the rotation threshold (180 days) is enforced * by comparing `lastRotationAt` (persisted in SharedPreferences) to * `System.currentTimeMillis()`. * * @see KeystoreManager * @see SupplyChainMonitor */@Singletonclass DynamicRotationManager @Inject constructor(    private val context: Context,    private val keystoreManager: KeystoreManager,) {    private val prefs: SharedPreferences by lazy {        context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)    }    /**     * Get the current master key alias.     *     * On first launch, this is `nous.master.v1`. After each rotation, the     * version suffix is incremented (v2, v3, ...).     *     * Callers that need to encrypt/decrypt data should call this to get     * the alias, then pass it to [KeystoreManager.encrypt] / [decrypt].     */    val currentMasterAlias: String        get() = prefs.getString(KEY_CURRENT_ALIAS, DEFAULT_ALIAS) ?: DEFAULT_ALIAS    /**     * Epoch millis when the master key was last rotated.     *     * On first launch (no rotation has ever happened), this is the time     * of the first call to [maybeRotate] — i.e., the key's creation time.     */    val lastRotationAt: Long        get() = prefs.getLong(KEY_LAST_ROTATION, 0L)    /**     * Whether the master key is due for rotation (>= 180 days since last rotation).     */    val isRotationDue: Boolean        get() {            val now = System.currentTimeMillis()            val elapsed = now - lastRotationAt            return elapsed >= ROTATION_INTERVAL_MS        }    /**     * Rotate the master key if 180 days have passed.     *     * Idempotent — calling it multiple times within the rotation window     * is a no-op. Safe to call on every app start.     *     * @return true if rotation was performed, false if not yet due.     */    fun maybeRotate(): Boolean {        if (!isRotationDue) return false        val oldAlias = currentMasterAlias        val newAlias = nextAlias(oldAlias)        Timber.tag("NOUS.Security").i(            "Rotating master key: %s → %s (after %d days)",            oldAlias, newAlias, (System.currentTimeMillis() - lastRotationAt) / DAY_MS,        )        // Generate the new key.        val level = keystoreManager.generateKey(newAlias, requireAuth = false)        if (level == null) {            Timber.tag("NOUS.Security").w("Master key rotation FAILED — keeping old key.")            return false        }        // NOTE: Re-encryption of existing data is the caller's responsibility        // (CredentialVaultImpl, EncryptedStorage, BackupRestoreManager each        // know what they've stored and can re-encrypt in the background).        // We just bump the alias pointer; old data encrypted with the old        // alias remains readable until the old key is deleted (which happens        // only after re-encryption completes — callers signal via [deleteOldKey]).        prefs.edit()            .putString(KEY_CURRENT_ALIAS, newAlias)            .putLong(KEY_LAST_ROTATION, System.currentTimeMillis())            .apply()        return true    }    /**     * Force a rotation NOW, regardless of the time-based schedule.     *     * Called by [SupplyChainMonitor] when it detects a HIGH/CRITICAL threat.     * The threat may have observed the current key (e.g., via Frida hooking),     * so we rotate immediately to invalidate it.     *     * @param reason why the forced rotation was triggered (audit log).     * @return true if rotation succeeded.     */    fun forceRotate(reason: String): Boolean {        Timber.tag("NOUS.Security").w("Forced rotation triggered: %s", reason)        val oldAlias = currentMasterAlias        val newAlias = nextAlias(oldAlias)        val level = keystoreManager.generateKey(newAlias, requireAuth = false)        if (level == null) {            Timber.tag("NOUS.Security").w("Forced rotation FAILED — keeping compromised key (no fallback).")            return false        }        // **FIX (audit Task ID: audit-m12-security P1)**: Do NOT delete the old        // key immediately. Previously, `keystoreManager.deleteKey(oldAlias)` was        // called here, which caused PERMANENT DATA LOSS for any data still        // encrypted with the old key.        //        // Now, both old + new keys coexist. The caller MUST call        // [deleteOldKey] after re-encrypting all data with the new key.        // We persist the old alias so [deleteOldKey] knows which key to remove.        prefs.edit()            .putString(KEY_CURRENT_ALIAS, newAlias)            .putString(KEY_PENDING_DELETE_ALIAS, oldAlias)            .putLong(KEY_LAST_ROTATION, System.currentTimeMillis())            .apply()        Timber.tag("NOUS.Security").i("Rotation complete — old key '%s' kept until re-encryption finishes. Call deleteOldKey() when done.", oldAlias)        return true    }    /**     * Delete the previous master key after re-encryption is complete.     *     * Called by data store managers (CredentialVaultImpl, etc.) once     * they've re-encrypted all data with the new key. Until this is called,     * both old and new keys coexist (so old data remains readable while     * re-encryption progresses).     *     * Also clears the pending-delete alias from prefs so we don't try to     * delete a key that's already gone on next boot.     */    fun deleteOldKey(oldAlias: String) {        keystoreManager.deleteKey(oldAlias)        // Clear the pending-delete marker.        prefs.edit().remove(KEY_PENDING_DELETE_ALIAS).apply()        Timber.tag("NOUS.Security").i("Old key '%s' deleted — re-encryption complete.", oldAlias)    }    /**     * Get the alias of the previous master key that's pending deletion.     *     * Returns null if no rotation is in progress (or if [deleteOldKey] was     * already called). Used by data store managers to know which key to     * decrypt old data with during re-encryption.     */    fun pendingDeleteAlias(): String? = prefs.getString(KEY_PENDING_DELETE_ALIAS, null)    /**     * Compute the next alias in the sequence.     *     * `nous.master.v1` → `nous.master.v2` → `nous.master.v3` → ...     */    private fun nextAlias(current: String): String {        val match = Regex("""^(.+)\.v(\d+)$""").find(current)        if (match == null) return "$current.v2"        val prefix = match.groupValues[1]        val version = match.groupValues[2].toInt() + 1        return "$prefix.v$version"    }    private companion object {        const val PREFS_NAME = "nous_key_rotation"        const val KEY_CURRENT_ALIAS = "current_master_alias"        const val KEY_LAST_ROTATION = "last_rotation_at"        const val KEY_PENDING_DELETE_ALIAS = "pending_delete_alias"        const val DEFAULT_ALIAS = "nous.master.v1"        const val ROTATION_INTERVAL_DAYS = 180L        const val DAY_MS = 24L * 60L * 60L * 1000L        const val ROTATION_INTERVAL_MS = ROTATION_INTERVAL_DAYS * DAY_MS    }}